+  IF plan->>'can_execute'<>'true' OR plan->>'fingerprint' IS DISTINCT FROM expected_fingerprint THEN
+    RAISE EXCEPTION 'link plan is blocked or stale' USING ERRCODE='55000';
+  END IF;
